    char *options = (char *)*data;
    ext3_fsblk_t block = 1;  // Default block number

    if (!options || strncmp(options, "sb=", 3) != 0) {
        return block;
    }

    // Skip the "sb=" prefix
    options += 3;

    char *endptr;
    unsigned long parsed_block = simple_strtoul(options, &endptr, 0);

    // Check for invalid characters after the number
    if (*endptr != '\0' && *endptr != ',' && *endptr != ' ') {
        printk(KERN_ERR "Invalid characters after superblock block number.");
        return block;
    }

    // Update the data pointer to the remaining options
    *data = (void *)endptr;

    // Ensure the parsed block is within a reasonable range
    if (parsed_block == 0) {
        return block;
    }

    block = parsed_block;
    return block;
}
